// The known-answer vectors the browser checks too (web/src/lib/crypto.test.ts),
// generated by internal/e2ee/vectors_test.go.
const vectorsFile = "../../../web/src/lib/e2ee.vectors.json"

type vectors struct {
	Content []struct {
		Key, Nonce, Entity, EntityID, Field, Plaintext, Value string
	} `json:"content"`
	Passphrase struct {
		Passphrase string `json:"passphrase"`
		Salt       string `json:"salt"`
		Iterations int    `json:"iterations"`
		AccountKey string `json:"accountKey"`
		Wrapped    string `json:"wrapped"`
	} `json:"passphrase"`
	Recovery struct {
		Raw        string `json:"raw"`
		Text       string `json:"text"`
		AccountKey string `json:"accountKey"`
		Wrapped    string `json:"wrapped"`
	} `json:"recovery"`
}

func load(t *testing.T) vectors {
	t.Helper()
	raw, err := os.ReadFile(vectorsFile)
	if err != nil {
		t.Fatal(err)
	}
	var v vectors
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	if len(v.Content) == 0 {
		t.Fatal("no content vectors")
	}
	return v
}

func unhex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func TestContentVectors(t *testing.T) {
	for _, c := range load(t).Content {
		key := unhex(t, c.Key)
		got, err := SealWithNonce(key, unhex(t, c.Nonce), c.Entity, c.EntityID, c.Field, c.Plaintext)
		if err != nil || got != c.Value {
			t.Fatalf("%s.%s: seal = %q, %v; want %q", c.Entity, c.Field, got, err, c.Value)
		}
		pt, err := Open(key, c.Entity, c.EntityID, c.Field, c.Value)
		if err != nil || pt != c.Plaintext {
			t.Fatalf("%s.%s: open = %q, %v", c.Entity, c.Field, pt, err)
		}
		// Moved to another field or entity, it no longer opens.
		if _, err := Open(key, c.Entity, c.EntityID, "other", c.Value); !errors.Is(err, ErrDecrypt) {
			t.Fatalf("opened under another field: %v", err)
		}
		if _, err := Open(key, c.Entity, "other-id", c.Field, c.Value); !errors.Is(err, ErrDecrypt) {
			t.Fatalf("opened under another id: %v", err)
		}
	}
}

func TestSealRoundTripAndEnvelope(t *testing.T) {
	key := bytes.Repeat([]byte{7}, KeyBytes)
	v, err := Seal(key, "section", "s1", "name", "To plant")
	if err != nil || !e2ee.IsEnvelope(v) {
		t.Fatalf("seal = %q, %v", v, err)
	}
	if pt, err := Open(key, "section", "s1", "name", v); err != nil || pt != "To plant" {
		t.Fatalf("open = %q, %v", pt, err)
	}
	if w, _ := Seal(key, "section", "s1", "name", "To plant"); w == v {
		t.Fatal("two seals share a nonce")
	}
	other := bytes.Repeat([]byte{8}, KeyBytes)
	if _, err := Open(other, "section", "s1", "name", v); !errors.Is(err, ErrDecrypt) {
		t.Fatalf("opened with another key: %v", err)
	}
	for _, bad := range []string{"plain", "enc:v1:", "enc:v1:!!!!", "enc:v2:" + strings.Repeat("A", 40)} {
		if _, err := Open(key, "section", "s1", "name", bad); !errors.Is(err, ErrDecrypt) {
			t.Fatalf("%q: %v", bad, err)
		}
	}
}

func TestKeyWrapRFC3394(t *testing.T) {
	// RFC 3394 section 4.6: 256-bit KEK, 256-bit key.
	kek := unhex(t, "000102030405060708090A0B0C0D0E0F101112131415161718191A1B1C1D1E1F")
	key := unhex(t, "00112233445566778899AABBCCDDEEFF000102030405060708090A0B0C0D0E0F")
	w, err := Wrap(kek, key)
	if err != nil || strings.ToUpper(hex.EncodeToString(w)) != "28C9F404C4B810F4CBCCB35CFB87F8263F5786E2D80ED326CBC7F0E71A99F43BFB988B9B7A02DD21" {
		t.Fatalf("wrap = %x, %v", w, err)
	}
	back, err := Unwrap(kek, w)
	if err != nil || !bytes.Equal(back, key) {
		t.Fatalf("unwrap = %x, %v", back, err)
	}
	if _, err := Unwrap(bytes.Repeat([]byte{1}, 32), w); !errors.Is(err, ErrWrongSecret) {
		t.Fatalf("wrong kek: %v", err)
	}
}

func TestPassphraseAndRecoveryVectors(t *testing.T) {
	v := load(t)
	b64 := base64.RawURLEncoding
	old := MinIterations
	MinIterations = v.Passphrase.Iterations
	t.Cleanup(func() { MinIterations = old })
	rec := e2ee.KeyRecord{Version: 1, KDF: e2ee.KDFPBKDF2SHA256, Salt: b64.EncodeToString(unhex(t, v.Passphrase.Salt)), Iterations: v.Passphrase.Iterations,
		WrappedByPassphrase: v.Passphrase.Wrapped, WrappedByRecovery: v.Recovery.Wrapped}
	dek, err := UnlockWithPassphrase(rec, v.Passphrase.Passphrase)
	if err != nil || hex.EncodeToString(dek) != v.Passphrase.AccountKey {
		t.Fatalf("passphrase unlock = %x, %v", dek, err)
	}
	if _, err := UnlockWithPassphrase(rec, "wrong horse battery staple"); !errors.Is(err, ErrWrongSecret) {
		t.Fatalf("wrong passphrase: %v", err)
	}
	raw, err := ParseRecoveryKey(strings.ToLower(v.Recovery.Text))
	if err != nil || hex.EncodeToString(raw) != v.Recovery.Raw {
		t.Fatalf("recovery parse = %x, %v", raw, err)
	}
	dek, err = UnlockWithRecoveryKey(rec, v.Recovery.Text)
	if err != nil || hex.EncodeToString(dek) != v.Recovery.AccountKey {
		t.Fatalf("recovery unlock = %x, %v", dek, err)
	}
	typo := []byte(v.Recovery.Text)
	typo[0] ^= 1
	if _, err := ParseRecoveryKey(string(typo)); !errors.Is(err, ErrRecoveryFormat) {
		t.Fatalf("typo: %v", err)
	}
	// Bounds: devices refuse too few and too many iterations; so does ot.
	MinIterations = old
	for _, n := range []int{1000, 99_999, 10_000_001} {
		bad := rec
		bad.Iterations = n
		if _, err := UnlockWithPassphrase(bad, v.Passphrase.Passphrase); !errors.Is(err, ErrIterations) {
			t.Fatalf("%d iterations: %v", n, err)
		}
	}
	if !NeedsNormalisation("café passphrase") || NeedsNormalisation(v.Passphrase.Passphrase) {
		t.Fatal("NeedsNormalisation")
	}
}

// TestServerDoesNotLinkCrypt (mcp-projects 4.2): the server binary runs no
// content cryptography; only the command-line client imports this package.
func TestServerDoesNotLinkCrypt(t *testing.T) {
	gobin, err := exec.LookPath("go")
	if err != nil {
		if gobin, err = exec.LookPath(filepath.Join(os.Getenv("GOROOT"), "bin", "go")); err != nil {
			t.Skip("the go command is not on PATH")
		}
	}
	out, err := exec.Command(gobin, "list", "-deps", "../../../cmd/opentodo").CombinedOutput()
	if err != nil {
		t.Fatalf("go list: %v\n%s", err, out)
	}
	if bytes.Contains(out, []byte("internal/e2ee/crypt")) {
		t.Fatal("the server binary links internal/e2ee/crypt")
	}
	out, err = exec.Command(gobin, "list", "-deps", "../../../cmd/ot").CombinedOutput()
	if err != nil {
		t.Fatalf("go list ot: %v\n%s", err, out)
	}
	if !bytes.Contains(out, []byte("internal/e2ee/crypt")) {
		t.Skip("ot does not link internal/e2ee/crypt yet")
	}
}
